import React, { useState, useEffect } from 'react';
import API from '../utils/api';
import toast from 'react-hot-toast';

const Reports = () => {
  const [customers, setCustomers] = useState([]);
  const [payments, setPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [reportType, setReportType] = useState('customers');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [customersRes, paymentsRes] = await Promise.all([
        API.get('/customers'),
        API.get('/payments'),
      ]);
      setCustomers(customersRes.data.data);
      setPayments(paymentsRes.data.data);
    } catch (error) {
      toast.error('Failed to load data');
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const exportCSV = (data, filename) => {
    if (!data || data.length === 0) {
      toast.error('No data to export');
      return;
    }

    const headers = Object.keys(data[0]);
    const csv = [
      headers.join(','),
      ...data.map(row => headers.map(h => `"${row[h] || ''}"`).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${filename}_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success('Export started!');
  };

  if (loading) {
    return <div className="loading">Loading reports...</div>;
  }

  // Customer Report Data
  const customerReportData = customers.map(c => ({
    Name: c.name,
    'Customer ID': c.customerId,
    'Monthly Fee': c.monthlyFee,
    'Pending Dues': c.pendingDues || 0,
    Phone: c.phone || '',
    Status: c.status,
    'Payment Status': c.paymentStatus,
  }));

  // Payment Report Data
  const paymentReportData = payments.map(p => ({
    'Receipt #': p.receiptNumber,
    Date: new Date(p.date).toLocaleDateString(),
    'Customer ID': p.customerId,
    'Customer Name': p.customerName,
    Amount: p.amount,
    Month: p.billingMonth,
    Method: p.method,
  }));

  // Dues Report Data
  const duesReportData = customers
    .filter(c => c.pendingDues > 0 || c.paymentStatus === 'Unpaid')
    .map(c => ({
      Name: c.name,
      'Customer ID': c.customerId,
      'Monthly Fee': c.monthlyFee,
      'Pending Dues': c.pendingDues || 0,
      'Payment Status': c.paymentStatus,
      Phone: c.phone || '',
    }));

  const reports = [
    { id: 'customers', label: '📋 Customer Report', data: customerReportData },
    { id: 'payments', label: '💰 Payment Report', data: paymentReportData },
    { id: 'dues', label: '⚠️ Dues Report', data: duesReportData },
  ];

  const currentReport = reports.find(r => r.id === reportType);

  return (
    <div>
      <h2 style={styles.pageTitle}>📊 Reports</h2>

      {/* Report Type Selector */}
      <div style={styles.reportSelector}>
        {reports.map((r) => (
          <button
            key={r.id}
            style={{
              ...styles.reportBtn,
              background: reportType === r.id ? '#2a7de1' : 'white',
              color: reportType === r.id ? 'white' : '#1a2a3a',
            }}
            onClick={() => setReportType(r.id)}
          >
            {r.label}
          </button>
        ))}
      </div>

      {/* Export Button */}
      <div style={styles.exportContainer}>
        <button
          style={styles.exportBtn}
          onClick={() => exportCSV(currentReport?.data || [], reportType)}
          disabled={!currentReport?.data || currentReport.data.length === 0}
        >
          📥 Export CSV
        </button>
        <span style={styles.recordCount}>
          {currentReport?.data?.length || 0} records
        </span>
      </div>

      {/* Report Table */}
      <div style={styles.tableContainer}>
        {currentReport && currentReport.data.length > 0 ? (
          <table style={styles.table}>
            <thead>
              <tr>
                {Object.keys(currentReport.data[0]).map((key) => (
                  <th key={key}>{key}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {currentReport.data.map((row, index) => (
                <tr key={index}>
                  {Object.values(row).map((value, i) => (
                    <td key={i}>{value}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <div style={styles.emptyState}>No data available for this report</div>
        )}
      </div>
    </div>
  );
};

const styles = {
  pageTitle: {
    fontSize: '22px',
    fontWeight: '700',
    color: '#1a2a3a',
    marginBottom: '20px',
  },
  reportSelector: {
    display: 'flex',
    gap: '12px',
    flexWrap: 'wrap',
    marginBottom: '20px',
  },
  reportBtn: {
    padding: '10px 20px',
    border: '2px solid #e2eaf2',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: '0.2s',
  },
  exportContainer: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '20px',
    flexWrap: 'wrap',
    gap: '12px',
  },
  exportBtn: {
    padding: '10px 24px',
    background: '#28a745',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    fontSize: '14px',
    fontWeight: '600',
    cursor: 'pointer',
    transition: '0.2s',
  },
  recordCount: {
    fontSize: '14px',
    color: '#6b7f99',
  },
  tableContainer: {
    background: 'white',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
    overflow: 'hidden',
    maxHeight: '500px',
    overflowY: 'auto',
  },
  table: {
    width: '100%',
    borderCollapse: 'collapse',
    fontSize: '13px',
  },
  emptyState: {
    padding: '40px',
    textAlign: 'center',
    color: '#6b7f99',
  },
};

export default Reports;
